// Code in JavaScript1 — extraire count
const html = $input.item.json.data;

// ✅ Aller chercher le keyword directement depuis le Loop Over Items
const keyword = $('Loop Over Items').item.json.keyword;

const matchCount = html.match(/(\d+)\s+consultation[s]?\s+trouv[ée][es]*/i);
const matchZero = html.match(/aucune\s+consultation\s+trouv[ée][e]*/i);

let count = 0;
if (matchCount) {
  count = parseInt(matchCount[1]);
} else if (matchZero) {
  count = 0;
}

return [{
  json: {
    keyword,
    count,
    hasOffers: count > 0,
    status: count > 0 ? `✅ ${count} offres` : '❌ Aucune offre'
  }
}];

// Code in JavaScript2 — branche TRUE (count == 0)
const workflowStaticData = $getWorkflowStaticData('global');
const keywordToRemove = $input.item.json.keyword;

// Vérification de sécurité
if (!workflowStaticData.keywords) {
  return [{ json: { error: 'Liste non initialisée', keyword: keywordToRemove } }];
}

// Supprimer le mot-clé sans offre
workflowStaticData.keywords = workflowStaticData.keywords.filter(
  kw => kw !== keywordToRemove
);

console.log(`🗑️ Supprimé : "${keywordToRemove}"`);
console.log(`📋 Restants : ${workflowStaticData.keywords.length}`);

return [{
  json: {
    action: 'supprimé',
    keyword: keywordToRemove,
    nb_restants: workflowStaticData.keywords.length,
    liste_restante: workflowStaticData.keywords
  }
}];
